#!/usr/bin/env bash
# shellcheck disable=SC2034  # constants consumed by report_html/head.sh after sourcing
# @module pipeline/_branding
# @description Brik branding assets embedded into HTML reports.
# Logo is the official Brik mark resized to 128x128 (covers retina 2x
# display at 64px) and base64-encoded so the HTML report stays self-
# contained (no external image fetches when archived as CI artifact).
# Regenerate via:
#   sips -s format png -Z 128 docs/getbrik.png --out /tmp/g.png \
#     && b64=$(base64 < /tmp/g.png | tr -d '\\n')

[[ -n "${_BRIK_PIPELINE_BRANDING_LOADED:-}" ]] && return 0
_BRIK_PIPELINE_BRANDING_LOADED=1

BRIK_LOGO_B64=""
BRIK_HOME_URL="https://github.com/getbrik"
